(() => {
  const btn=document.querySelector('#readBtn'), host=document.querySelector('#oracleNarrativeResult'), rawEl=document.querySelector('#resultText');
  if(!btn||!host||!rawEl)return;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const terms={
    '日主':['日主','八字日柱天干，代表你承受事情、出手做事嘅核心方式。'], '月令':['月令','出生月份嘅季節力量，用嚟判斷一個五行當時有幾大氣勢。'], '十神':['十神','將其他天干同日主嘅生剋關係分類，對應資源、責任、輸出、財務同同伴。'], '命宮':['命宮','紫微入面代表你面對世界、建立性格同人生主軸嘅位置。'], '官祿宮':['官祿宮','紫微入面對應工作角色、職場責任、專業方向同名位。'], '財帛宮':['財帛宮','紫微入面觀察收入模式、資源管理及你點樣將能力變成回報。'], '夫妻宮':['夫妻宮','觀察親密關係互動模式及磨合課題，唔係直接預言婚姻。'], '四化':['四化','化祿、化權、化科、化忌，分別提示資源、推動力、可見度及卡點。'], '值符':['值符','奇門局中嘅主帥星，提示今次事情最需要依靠嘅核心資源。'], '值使':['值使','奇門局中代表事情落地方式嘅門，提示應該點行動。'], '九宮':['九宮','奇門將時間、方向、人物及事情分到九個位置，方便逐格核對。'], '本卦':['本卦','問題目前表面結構；先讀現況，再決定要不要改變。'], '互卦':['互卦','本卦內部嘅中段結構，提示真正卡住事情嘅因素。'], '變卦':['變卦','動爻之後嘅發展方向，係趨勢提示，不是必然結果。'], '動爻':['動爻','卦入面最需要處理嘅變化位置，將抽象提醒落到一件事。'], '小六壬':['小六壬','以大安、留連、速喜、赤口、小吉、空亡判斷當下節奏，唔取代完整命盤。'], 'Lagna':['Lagna','印度占星上升點，描述你出場方式、外在反應及人生開局。'], 'Nakshatra':['Nakshatra','月亮所在月宿，細分情緒習慣、動機及反應節奏。'], 'Bhava':['Bhava','印度占星十二宮，將行星功能放入工作、財務、關係等生活領域。'], 'Dasha':['Vimshottari Dasha','印度占星以行星主周期排列人生時間層，完整餘額要用精確星曆覆核。']};
  const linkTerms=s=>Object.keys(terms).sort((a,b)=>b.length-a.length).reduce((out,t)=>out.replaceAll(t,`<button class="rich-term" data-term="${t}">${t}</button>`),esc(s));
  const seed=s=>[...s].reduce((n,c)=>(n*31+c.charCodeAt(0))%997,7);
  const val=id=>document.querySelector('#'+id)?.value||'';
  const selected=()=>document.querySelector('.method.active')?.dataset.name||'綜合解讀';
  const card=(n,title,body)=>`<section class="rich-block"><span class="rich-num">0${n}</span><div><h4>${title}</h4><p>${linkTerms(body)}</p></div></section>`;
  function partner(q){const s=seed(q),year=2027+s%3,months=['3 月','5 月','8 月','10 月','11 月'],places=['進修課程／工作坊','跨部門合作場合','書店、展覽或文化活動','朋友組織嘅小型聚會','轉工面試或專業社群'];return `<details class="partner-panel" open><summary>未來伴侶 · 推測人物檔案（可展開）</summary><div class="partner-layout"><img src="./public/partner-oracle.png" alt="原創韓漫風格未來伴侶推測形象"><div class="partner-copy"><p><b>相遇窗口：</b>${year} 年 ${months[s%months.length]}；屬於可能時段，唔係保證事件。</p><p><b>可能地點：</b>${places[s%places.length]}。</p><p><b>可能行業：</b>${['產品／設計','教育／研究','醫療／照護','金融／營運','媒體／內容策略'][s%5]}。</p><p><b>外貌輪廓：</b>輪廓清晰、眼神安靜，衣著俐落，偏深色中性風；圖像只係根據象意生成嘅視覺化推測。</p><p><b>說話方式：</b>先聽後答，句子短而精準，遇到重要決定會問證據同時間表。</p><p><b>表達感情：</b>用安排時間、記住細節、實際幫手表達，多過高調示愛。</p><p><b>優點／缺點：</b>可靠、有邏輯、守承諾；但慢熱、固執，壓力大時會收埋自己。</p><p><b>最易爭拗：</b>你想即刻講清楚，對方想先沉澱；亦可能因工作優先次序及回覆速度起衝突。</p><p><b>相處方法：</b>預先講清楚界線、每星期固定一次對話，將猜測改成直接提問。</p></div></div></details>`}
  function render(){const method=selected(),raw=rawEl.textContent||'',q=(raw.match(/問題：「([^」]+)」/)||[])[1]||val('question')||'目前最重要的選擇',s=seed(q),styles=[['外在呈現','你表面上顯得冷靜、識分析，遇到選擇會先比較條件，唔想畀人睇到自己未有答案。'],['內在性格','你其實對失去主導權好敏感；一旦相信某件事，就會默默揹起責任，直到身體同情緒先出聲。'],['真正煩惱','你問緊嘅唔只係邊份工好，而係：揀錯之後，仲有冇空間翻身？'],['盤面術語','今次最值得追蹤嘅係 '+(method==='紫微斗數'?'命宮、官祿宮、財帛宮、四化':method==='八字'?'日主、月令、十神、流年／流月／流日':method==='奇門遁甲'?'九宮、值符、值使、九星、八門、八神':method==='印度占星'?'Lagna、Moon sign、Nakshatra、Bhava、Dasha':method==='小六壬'?'小六壬六神、落宮、當下節奏':'本卦、互卦、變卦、動爻、體用')+'。'],['白話解碼','命理術語唔係判決書，而係一套觀察鏡：幫你分辨係長期傾向、當下節奏，定係一個需要補證據嘅盲點。'],['三條現實影響','工作：揀有清楚權責、回饋週期同 90 日成果嘅位置。財運：先問實際薪酬、試用期、加薪條件，唔好只聽願景。感情：你需要安全感同坦白界線，唔適合長期靠估。'],['可能事件窗口','未來 7 日適合收集資料及追問條件；未來 1 至 3 個月可能出現一次工作角色或合作模式調整。呢啲係推測窗口，必須由現實訊息核對。'],['你而家要做嘅事','將選項按上司清晰度、實際權限、學習空間、收入穩定、團隊界線各評 1 至 5 分；最低分低於 2，先要求對方補充書面答案。']];
    host.innerHTML=`<div class="oracle-dialogue"><img src="./public/teaser/male-invite.png" alt="玄頁道令韓漫命理師"><div><span>玄頁道令 · ${method}</span><strong>「你唔係冇答案。你只係唔想再為別人嘅混亂埋單。」</strong><em>以下係推測與行動框架，唔係百分百預言。</em></div></div><div class="rich-grid">${styles.map((x,i)=>card(i+1,x[0],x[1])).join('')}</div>${partner(q)}<div class="term-drawer" id="richTermDrawer"><b>點擊上面任何術語</b><span>我會用白話解釋佢代表咩、點樣影響你。</span></div><div class="coming-soon"><span>進階報告</span><b>COMING SOON</b><small>完整流限、交叉盤及個人化長篇章節正在整理，現階段先免費睇完整 Demo。</small></div>`;
    host.hidden=false;rawEl.hidden=true;
    const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');reveal.unobserve(entry.target)}}),{threshold:.16});
    host.querySelectorAll('.rich-block,.partner-panel,.term-drawer,.coming-soon').forEach((el,i)=>{el.style.setProperty('--beat',`${Math.min(i*.07,.56)}s`);reveal.observe(el)});
    host.querySelectorAll('.rich-term').forEach(b=>b.onclick=()=>{const d=terms[b.dataset.term],drawer=host.querySelector('#richTermDrawer');drawer.innerHTML=`<b>${d[0]}</b><span>${d[1]}</span>`;drawer.classList.add('is-active')});
  }
  btn.addEventListener('click',()=>{setTimeout(render,1200)});
  new MutationObserver(()=>{if(document.querySelector('#resultCard')?.classList.contains('is-open'))setTimeout(render,80)}).observe(rawEl,{childList:true,characterData:true,subtree:true});
})();
